                neighbor_sum += x_perm[j]
            perm_local = (
                n_factor * x_perm[c_index] * neighbor_sum / s
            )
            if abs(perm_local) >= abs(observed[c_index]):
                hits[c_index] += 1
    cell_stats = [
        (
            observed[c_index],
            Decimal(1) if not adjacency[c_index]
            else Decimal(hits[c_index]) / factorial,
        )
        for c_index in range(n)
    ]

